mapper.insert:
INSERT INTO transactions (
    id, account_id, transaction_type, amount, status,
    created_at, completed_at, order_id, fail_reason,
    relative_account_number, relative_account_username
) VALUES (
             #{id}, #{accountId}, #{transactionType}, #{amount}, #{status},
             #{createdAt}, #{completedAt}, #{orderId}, #{failReason},
             #{relativeAccountNumber}, #{relativeAccountUsername}
         )

mapper.select:
select t.id, transaction_type, amount, status, t.completed_at, t.fail_reason, symbol, quantity, price
from transactions t join orders o on t.order_id = o.id
where t.account_id = #{accountId}
and (transaction_type like 'SELL' or transaction_type like 'BUY')

    and t.completed_at >= #{startDate} and t.completed_at <= #{endDate}

order by t.completed_at desc;

select id, transaction_type, amount, status, completed_at, fail_reason, relative_account_number, relative_account_username
from transactions
where account_id = #{accountId}
and (transaction_type = 'DEPOSIT' or transaction_type = 'WITHDRAW');
